const ELEMENT_PROP_KEYS = new Set(["theme","player","title","flash","playerScore","stagger","accent","fontFamily","ink","background","scale","delay","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  player: "RMC",
  title: "HIGH SCORES",
  flash: "NEW HIGH SCORE",
  playerScore: 999990,
  stagger: 3,
  accent: "#3B5BFD",
  fontFamily: "Silkscreen",
  scale: 1,
  delay: 0,
  speed: 1,
};

type HighScoreElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof HighScoreBase>;

const HighScoreInner = forwardRef<
  HTMLDivElement,
  HighScoreElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<HighScore>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <HighScoreBase
          {...(componentProps as unknown as ComponentProps<typeof HighScoreBase>)}
        />
      </div>
    </Sequence>
  );
});

export const HighScore = Interactive.withSchema({
  Component: HighScoreInner,
  componentName: "<HighScore>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
